### Solution:
```java
import java.util.*;

class DirectedGraph {
    private Map<String, List<String>> graph;

    public DirectedGraph() {
        graph = new HashMap<>();
    }

    public void AddNode(String nodeId) {
        graph.put(nodeId, new ArrayList<>());
    }

    public void LinkDirectional(String fromNode, String toNode) {
        graph.get(fromNode).add(toNode);
    }

    public List<String> DFSTraversal(String startNode) {
        List<String> visited = new ArrayList<>();
        Set<String> visitedSet = new HashSet<>();
        DFS(startNode, visited, visitedSet);
        return visited;
    }

    private void DFS(String currentNode, List<String> visited, Set<String> visitedSet) {
        visited.add(currentNode);
        visitedSet.add(currentNode);
        for (String neighbor : graph.get(currentNode)) {
            if (!visitedSet.contains(neighbor)) {
                DFS(neighbor, visited, visitedSet);
            }
        }
    }
}

