### Problem:
You are given a directed graph represented by a list of edges. Each edge is a tuple (source, destination) where source and destination are integers representing the nodes. Your task is to implement a function to detect if the given graph contains a cycle.

Write a function `bool HasCycle(List<Tuple<int, int>> edges)` that takes in a list of edges and returns true if the graph contains a cycle, and false otherwise.

Example:
For the input `edges = [(1, 2), (2, 3), (3, 4), (4, 1)]`, the graph contains a cycle (1 -> 2 -> 3 -> 4 -> 1), so the function should return true.

For the input `edges = [(1, 2), (2, 3), (3, 4)]`, the graph does not contain a cycle, so the function should return false.

### Solution:
```csharp
using System;
using System.Collections.Generic;

public class CycleDetection
{
    public bool HasCycle(List<Tuple<int, int>> edges)
    {
        Dictionary<int, List<int>> graph = new Dictionary<int, List<int>>();
        foreach (var edge in edges)
        {
            if (!graph.ContainsKey(edge.Item1))
            {
                graph[edge.Item1] = new List<int>();
            }
            graph[edge.Item1].Add(edge.Item2);
        }

        HashSet<int> visited = new HashSet<int>();
        HashSet<int> recursionStack = new HashSet<int>();

        foreach (var node in graph.Keys)
        {
            if (IsCyclic(node, graph, visited, recursionStack))
            {
                return true;
            }
        }
        return false;
    }

    private bool IsCyclic(int node, Dictionary<int, List<int>> graph, HashSet<int> visited, HashSet<int> recursionStack)
    {
        if (recursionStack.Contains(node))
        {
            return true;
        }
        if (visited.Contains(node))
        {
            return false;
        }

        visited.Add(node);
        recursionStack.Add(node);

        if (graph.ContainsKey(node))
        {
            foreach (var neighbor in graph[node])
            {
                if (IsCyclic(neighbor, graph, visited, recursionStack))
                {
                    return true;
                }
            }
        }

        recursionStack.Remove(node);
        return false;
    }
}
