You are given a code snippet that appears to be part of a larger program for solving the maximum flow problem using the Ford-Fulkerson algorithm. Your task is to implement the `addEdge` and `fordFulkerson` functions to complete the program.

The `addEdge` function takes three parameters: `from`, `to`, and `capacity`, representing the source vertex, destination vertex, and the capacity of the edge between them, respectively. The `fordFulkerson` function takes two parameters: `source` and `sink`, representing the source and sink vertices, and returns the maximum flow from the source to the sink in the given graph.

Your task is to complete the implementation of the `addEdge` and `fordFulkerson` functions to ensure the program correctly computes the maximum flow in a given graph.

### Solution:
```cpp
#include <iostream>
#include <vector>
#include <climits>

using namespace std;

const int MAX_V = 100; // Maximum number of vertices

vector<vector<int>> capacity(MAX_V, vector<int>(MAX_V, 0));
vector<vector<int>> residual(MAX_V, vector<int>(MAX_V, 0));
vector<int> parent(MAX_V, -1);

void addEdge(int from, int to, int cap) {
    capacity[from][to] = cap;
}

bool bfs(int source, int sink, vector<int>& parent) {
    vector<bool> visited(MAX_V, false);
    vector<int> queue;
    queue.push_back(source);
    visited[source] = true;
    parent[source] = -1;

    while (!queue.empty()) {
        int u = queue.front();
        queue.erase(queue.begin());

        for (int v = 0; v < MAX_V; v++) {
            if (!visited[v] && residual[u][v] > 0) {
                queue.push_back(v);
                parent[v] = u;
                visited[v] = true;
            }
        }
    }

    return visited[sink];
}

int fordFulkerson(int source, int sink) {
    int maxFlow = 0;

    while (bfs(source, sink, parent)) {
        int pathFlow = INT_MAX;
        for (int v = sink; v != source; v = parent[v]) {
            int u = parent[v];
            pathFlow = min(pathFlow, residual[u][v]);
        }

        for (int v = sink; v != source; v = parent[v]) {
            int u = parent[v];
            residual[u][v] -= pathFlow;
            residual[v][u] += pathFlow;
        }

        maxFlow += pathFlow;
    }

    return maxFlow;
}

int main() {
