    addEdge(0, 1, 3);
    addEdge(0, 2, 2);
    addEdge(1, 2, 1);
    addEdge(1, 3, 3);
    addEdge(2, 3, 2);

    int ans = fordFulkerson(0, vertexNum - 1);
    cout << ans << endl;

    return 0;
}
```

