Write a function `int countDistinctPaths(vector<vector<int>>& graph, int cur)` that takes in the adjacency list `graph` and the starting node `cur`, and returns the count of distinct paths from `cur` to all other nodes in the graph.

The function should use a depth-first search (DFS) algorithm to traverse the graph and count the distinct paths. A distinct path is defined as a unique sequence of nodes from the starting node `cur` to a destination node, where no node is repeated in the path.

You can assume that the input graph is non-empty and the starting node `cur` is a valid node in the graph.

Example:
For the graph represented by the adjacency list `graph = [[1, 2], [2, 3], [3], [4], []]` and the starting node `cur = 0`, the distinct paths are as follows:
- From node 0 to node 1: 0 -> 1
- From node 0 to node 2: 0 -> 2
- From node 0 to node 3: 0 -> 2 -> 3
- From node 0 to node 4: 0 -> 2 -> 3 -> 4
So, the function call `countDistinctPaths(graph, 0)` should return 4.

### Solution:
```cpp
#include <vector>
using namespace std;

class Solution {
public:
    int countDistinctPaths(vector<vector<int>>& graph, int cur) {
        int pathCount = 0;
        vector<bool> visited(graph.size(), false);
        dfs(graph, cur, visited, pathCount);
        return pathCount;
    }

    void dfs(vector<vector<int>>& graph, int cur, vector<bool>& visited, int& pathCount) {
        visited[cur] = true;
        for (int i = 0; i < graph[cur].size(); i++) {
            int nextNode = graph[cur][i];
            if (!visited[nextNode]) {
                pathCount++;
                dfs(graph, nextNode, visited, pathCount);
            }
        }
    }
};

