### Solution:
```python
class DepthFirstSearch:
    def __init__(self, graph):
        self.graph = graph
        self.visited = set()
        self.traversal_order = []

    def search(self, vertex):
        self._dfs(vertex)
        return self.traversal_order

    def _dfs(self, vertex):
        if vertex not in self.visited:
            self.visited.add(vertex)
            self.traversal_order.append(vertex)
            for neighbor in self.graph[vertex]:
                self._dfs(neighbor)


class BreadthFirstSearch:
    def __init__(self, graph):
        self.graph = graph
        self.visited = set()
        self.traversal_order = []

    def search(self, start_vertex):
        queue = [start_vertex]
        self.visited.add(start_vertex)

        while queue:
            vertex = queue.pop(0)
            self.traversal_order.append(vertex)
            for neighbor in self.graph[vertex]:
                if neighbor not in self.visited:
                    queue.append(neighbor)
                    self.visited.add(neighbor)

        return self.traversal_order


class ConnectedComponents:
    def __init__(self, graph):
        self.graph = graph
        self.visited = set()

    def find_components(self):
        components = []
        for vertex in self.graph:
            if vertex not in self.visited:
                component = set()
                self._dfs(vertex, component)
                components.append(component)
        return components

    def _dfs(self, vertex, component):
        if vertex not in self.visited:
            self.visited.add(vertex)
            component.add(vertex)
            for neighbor in self.graph[vertex]:
                self._dfs(neighbor, component)
```

