### Problem:
You are given a directed acyclic graph (DAG) represented as an adjacency matrix `graph[][]` with `n` vertices. Each cell `graph[from][to]` contains the weight of the edge from vertex `from` to vertex `to`. Additionally, an array `indegrees[]` is used to store the indegree of each vertex in the graph.

Your task is to implement a topological sorting algorithm to find the order in which the vertices can be visited, such that for every directed edge from vertex `u` to vertex `v`, `u` comes before `v` in the ordering. If the graph contains a cycle, the topological sorting is not possible, and the algorithm should return -1.

Implement the function `int tlsort()` to perform topological sorting on the given graph and return the order of vertices as a single integer if a valid topological ordering exists, or -1 if the graph contains a cycle.

The function signature is:
```cpp
int tlsort();
```

### Solution:
```cpp
#include <iostream>
#include <vector>
#include <queue>
using namespace std;

const int MAXN = 1005; // Maximum number of vertices

int graph[MAXN][MAXN]; // Adjacency matrix representing the graph
int indegrees[MAXN];    // Array to store the indegree of each vertex
int n;                  // Number of vertices in the graph

int tlsort() {
    vector<int> order; // Stores the topological order of vertices
    queue<int> q;      // Queue to perform BFS for topological sorting

    for (int i = 0; i < n; i++) {
        if (indegrees[i] == 0) {
            q.push(i); // Add vertices with indegree 0 to the queue
        }
    }

    while (!q.empty()) {
        int u = q.front();
        q.pop();
        order.push_back(u); // Add the vertex to the topological order

        for (int v = 0; v < n; v++) {
            if (graph[u][v] > 0) {
                indegrees[v]--; // Decrement the indegree of adjacent vertices
                if (indegrees[v] == 0) {
                    q.push(v); // Add vertices with updated indegree 0 to the queue
                }
            }
        }
    }

    if (order.size() != n) {
        return -1; // Graph contains a cycle, return -1
    } else {
        return order.size(); // Return the number of vertices in the topological order
    }
}

int main() {
    // Input graph and indegrees
    // ...

    int result = tlsort();
    if (result == -1) {
        cout << "Impossible\n";
    } else {
        cout << result << '\n';
    }

    return 0;
}
```

