You are given a maze represented as a grid of size N x N. Each cell in the grid is either empty (denoted by 0) or blocked (denoted by 1). You are also given a starting cell (x, y) and a target cell (p, q). Your task is to find the shortest path from the starting cell to the target cell by moving only in the four cardinal directions (up, down, left, right) and avoiding the blocked cells.

You need to implement the BFS (Breadth-First Search) algorithm to find the shortest path from the starting cell to the target cell. The BFS algorithm should consider only the empty cells as valid moves and should not traverse through blocked cells.

Your task is to write a function `shortestPath` that takes the following parameters:
- `N`: an integer representing the size of the grid (1 <= N <= 100)
- `maze`: a 2D array of integers representing the grid where 0 denotes an empty cell and 1 denotes a blocked cell
- `x`, `y`: integers representing the starting cell coordinates (0 <= x, y < N)
- `p`, `q`: integers representing the target cell coordinates (0 <= p, q < N)

The function should return an array of integers representing the shortest path from the starting cell to the target cell. If there is no valid path, return an empty array.

For example, given N = 3, maze = [[0, 1, 0], [0, 0, 0], [1, 1, 0]], x = 0, y = 0, p = 2, q = 2, the function should return [0, 1, 2, 5, 8].

### Solution:
```cpp
#include <iostream>
#include <queue>
#include <vector>
#include <cstring>

using namespace std;

const int MAX_N = 100;
int visited[MAX_N][MAX_N];
int dx[] = {1, -1, 0, 0};
int dy[] = {0, 0, 1, -1};
vector<int> track;

bool isValid(int x, int y, int N, const vector<vector<int>>& maze) {
    return (x >= 0 && x < N && y >= 0 && y < N && maze[x][y] == 0 && visited[x][y] == -1);
}

void BFS(int x, int y, int p, int q, int N, const vector<vector<int>>& maze) {
    queue<pair<int, int>> q;
    q.push({x, y});
    visited[x][y] = 0;

    while (!q.empty()) {
        int curX = q.front().first;
        int curY = q.front().second;
        q.pop();

        if (curX == p && curY == q) {
            int cur = visited[curX][curY];
            while (cur != 0) {
                track.push_back(cur);
                int nx = curX - dx[track.back() - 1];
                int ny = curY - dy[track.back() - 1];
                curX = nx;
                curY = ny;
                cur = visited[nx][ny];
            }
            return;
        }

        for (int i = 0; i < 4; i++) {
            int newX = curX + dx[i];
            int newY = curY + dy[i];
            if (isValid(newX, newY, N, maze)) {
                visited[newX][newY] = visited[curX][curY] + 1;
                q.push({newX, newY});
            }
        }
    }
}

vector<int> shortestPath(int N, const vector<vector<int>>& maze, int x, int y, int p, int q) {
    memset(visited, -1, sizeof(visited));
    BFS(x, y, p, q, N, maze);
    reverse(track.begin(), track.end());
    return track;
}

int main() {
    int N = 3;
    vector<vector<int>> maze = {{0, 1, 0}, {0, 0, 0}, {1, 1, 0}};
    int x = 0, y = 0, p = 2, q = 2;
    vector<int> result = shortestPath(N, maze, x, y, p, q);
    for (int i = 0; i < result.size(); i++) {
        cout << result[i] << " ";
    }
    return 0;
}
```

### Problem:
You are tasked with implementing a simple stack data structure using a linked list in C++. The stack should support the following operations:
1. `push`: Add an element to the top of the stack.
2. `pop`: Remove the element from the top of the stack and return its value.
3. `top`: Return the value of the element at the top of the stack without removing it.
4. `empty`: Return true if the stack is empty, false otherwise.

You need to implement the `Stack` class using a linked list to achieve the desired functionality. The `Node` class for the linked list is provided, and you should use it to build the stack.

Given code snippet for `Node` class:
```cpp
class Node {
public:
    int data;
    Node* next;
    Node(int val) : data(val), next(nullptr) {}
};
```

Your task is to complete the implementation of the `Stack` class with the specified operations using the provided `Node` class.

### Solution:
```cpp
#include <iostream>

class Node {
public:
    int data;
    Node* next;
    Node(int val) : data(val), next(nullptr) {}
};

class Stack {
private:
    Node* topNode;

public:
    Stack() : topNode(nullptr) {}

    void push(int val) {
        Node* newNode = new Node(val);
        newNode->next = topNode;
        topNode = newNode;
    }

    int pop() {
        if (topNode == nullptr) {
            std::cerr << "Error: Stack is empty\n";
            return -1; // Assuming -1 as an error value
        }
        int val = topNode->data;
        Node* temp = topNode;
        topNode = topNode->next;
        delete temp;
        return val;
    }

    int top() {
        if (topNode == nullptr) {
            std::cerr << "Error: Stack is empty\n";
            return -1; // Assuming -1 as an error value
        }
        return topNode->data;
    }

    bool empty() {
        return topNode == nullptr;
    }
};

int main() {
    Stack stack;
    stack.push(5);
    stack.push(10);
    stack.push(15);

    std::cout << "Top element: " << stack.top() << std::endl;
    std::cout << "Popped element: " << stack.pop() << std::endl;
    std::cout << "Top element after pop: " << stack.top() << std::endl;

    std::cout << "Is stack empty? " << (stack.empty() ? "Yes" : "No") << std::endl;

    return 0;
}
```

