```python
import heapq

class Graph:
    def __init__(self):
        self.adjacency_list = {}

    def add_edge(self, u, v, cost):
        if u not in self.adjacency_list:
            self.adjacency_list[u] = []
        self.adjacency_list[u].append((v, cost))

def heuristic_estimate(node, goal):
    # Implement the heuristic function to estimate the cost from the given node to the goal node
    # Example heuristic function for Euclidean distance in a 2D grid:
    # return ((node.x - goal.x) ** 2 + (node.y - goal.y) ** 2) ** 0.5

def aStar(graph, start, goal):
    open_set = [(0, start, [])]  # (estimated_total_cost, current_node, path)
    closed_set = set()

    while open_set:
        estimated_total_cost, current_node, path = heapq.heappop(open_set)
        if current_node == goal:
            return path + [current_node]

        if current_node in closed_set:
            continue

        closed_set.add(current_node)

        for neighbor, cost in graph.adjacency_list.get(current_node, []):
            if neighbor in closed_set:
                continue
            new_path = path + [current_node]
            estimated_cost_to_neighbor = len(new_path) + heuristic_estimate(neighbor, goal)
            heapq.heappush(open_set, (estimated_cost_to_neighbor, neighbor, new_path))

    return None  # No path found

def main():
    graph = Graph()
    # Initialize the graph by adding edges and their associated costs
    # Call the aStar function to find the shortest path from the start node to the goal node
    shortest_path = aStar(graph, start_node, goal_node)
    print(shortest_path)

if __name__ == "__main__":
    main()
