You are tasked with implementing a priority queue using a min-heap data structure. A priority queue is an abstract data type that operates similar to a regular queue or stack, but where each element has a priority associated with it. In a min-heap priority queue, the element with the smallest priority value should be dequeued first.

Your task is to implement the `PriorityQueue` class with the following methods:
- `enqueue(value, priority)`: Add a new element with the given value and priority to the priority queue.
- `dequeue()`: Remove and return the element with the highest priority in the priority queue.
- `isEmpty()`: Return true if the priority queue is empty, false otherwise.

You should implement the min-heap data structure to efficiently support these operations.

Example:
```javascript
const pq = new PriorityQueue();
pq.enqueue('task1', 3);
pq.enqueue('task2', 1);
pq.enqueue('task3', 2);
console.log(pq.dequeue()); // Output: 'task2'
console.log(pq.dequeue()); // Output: 'task3'
console.log(pq.dequeue()); // Output: 'task1'
console.log(pq.isEmpty()); // Output: true
```

### Solution:
```javascript
class PriorityQueue {
  constructor() {
    this.heap = [];
  }

  enqueue(value, priority) {
    const node = { value, priority };
    this.heap.push(node);
    this.bubbleUp(this.heap.length - 1);
  }

  dequeue() {
    if (this.isEmpty()) {
      throw new Error('Priority queue is empty');
    }
    const min = this.heap[0];
    const end = this.heap.pop();
    if (this.heap.length > 0) {
      this.heap[0] = end;
      this.sinkDown(0);
    }
    return min.value;
  }

  isEmpty() {
    return this.heap.length === 0;
  }

  bubbleUp(index) {
    const node = this.heap[index];
    while (index > 0) {
      const parentIndex = Math.floor((index - 1) / 2);
      const parent = this.heap[parentIndex];
      if (node.priority >= parent.priority) {
        break;
      }
      this.heap[parentIndex] = node;
      this.heap[index] = parent;
      index = parentIndex;
    }
  }

  sinkDown(index) {
    const length = this.heap.length;
    const node = this.heap[index];
    while (true) {
      const leftChildIndex = 2 * index + 1;
      const rightChildIndex = 2 * index + 2;
      let leftChild, rightChild;
      let swap = null;

      if (leftChildIndex < length) {
        leftChild = this.heap[leftChildIndex];
        if (leftChild.priority < node.priority) {
          swap = leftChildIndex;
        }
      }
      if (rightChildIndex < length) {
        rightChild = this.heap[rightChildIndex];
        if (
          (swap === null && rightChild.priority < node.priority) ||
          (swap !== null && rightChild.priority < leftChild.priority)
        ) {
          swap = rightChildIndex;
        }
      }
      if (swap === null) {
        break;
      }
      this.heap[index] = this.heap[swap];
      this.heap[swap] = node;
      index = swap;
    }
  }
}
```

