```

Write the `findOptimalTagReplacements()` method to find the optimal tag replacements based on the given tag pairs and the current tag indices.

### Solution:
```swift
public func findOptimalTagReplacements() -> [Int: Int] {
    var tagReplacements: [Int: Int] = [:]

    // Create a graph to represent the tag pairs
    var graph: [Int: Set<Int>] = [:]
    for pair in tagPairs {
        if graph[pair.0] == nil {
            graph[pair.0] = Set()
        }
        if graph[pair.1] == nil {
            graph[pair.1] = Set()
        }
        graph[pair.0]?.insert(pair.1)
        graph[pair.1]?.insert(pair.0)
    }

    // Perform a depth-first search to find connected components
    var visited: Set<Int> = Set()
    var components: [[Int]] = []
    for tag in graph.keys {
        if !visited.contains(tag) {
            var component: [Int] = []
            dfs(tag, &visited, &component, graph)
            components.append(component)
        }
    }

    // Determine the optimal replacements within each connected component
    for component in components {
        if component.count > 1 {
            for i in 0..<component.count - 1 {
                tagReplacements[component[i]] = component[i + 1]
            }
            tagReplacements[component.last!] = component.first!
        }
    }

    return tagReplacements
}

private func dfs(_ tag: Int, _ visited: inout Set<Int>, _ component: inout [Int], _ graph: [Int: Set<Int>]) {
    visited.insert(tag)
    component.append(tag)
    if let neighbors = graph[tag] {
        for neighbor in neighbors {
            if !visited.contains(neighbor) {
                dfs(neighbor, &visited, &component, graph)
            }
        }
    }
}
```

The `findOptimalTagReplacements()` method first constructs a graph representing the tag pairs and then performs a depth-first search to find connected components. Within each connected component, it determines the optimal tag replacements to minimize the number of replacements needed in the `replaceTags` method. The method returns the optimal tag replacements as a dictionary of tag indices.

