### Solution:
```rust
fn resolve_dependencies(modules: Vec<&str>) -> Vec<&str> {
    let mut graph = std::collections::HashMap::new();
    let mut visited = std::collections::HashSet::new();
    let mut result = Vec::new();

    for module in &modules {
        graph.insert(module.to_string(), Vec::new());
    }

    for module in &modules {
        let dependencies = get_dependencies(module);
        graph.insert(module.to_string(), dependencies);
    }

    for module in &modules {
        if !visited.contains(module) {
            dfs(module, &graph, &mut visited, &mut result);
        }
    }

    result
}

fn get_dependencies(module: &str) -> Vec<String> {
