### Problem:
You are tasked with implementing a dependency graph data structure in JavaScript. The graph should support adding dependencies between nodes and detecting circular dependencies.

You need to implement the `DependencyGraph` class with the following methods:
1. `addNode(id)`: Adds a node with the given id to the graph.
2. `addDependency(subjectId, dependentId)`: Adds a dependency between the node with id `subjectId` and the node with id `dependentId`.
3. `hasCircularDependencies()`: Returns true if the graph contains circular dependencies, otherwise false.

The `DependencyGraph` class should throw errors in the following scenarios:
- When attempting to add a dependency between nodes that do not exist in the graph.
- When a circular dependency is detected.

You should use the provided code snippet as a reference for error handling and dependency management.

### Solution:
```javascript
class DependencyGraph {
  constructor() {
    this.nodes = new Map();
  }

  addNode(id) {
    if (this.nodes.has(id)) {
      throw new Error(`Node with id ${id} already exists in the graph`);
    }
    this.nodes.set(id, { dependsOn: new Set(), dependedOnBy: new Set() });
  }

  addDependency(subjectId, dependentId, visited = new Set()) {
    if (!this.nodes.has(subjectId)) {
      throw new Error(`Dependency graph referenced node with id ${subjectId}, which was not in the node list`);
    }

    if (!this.nodes.has(dependentId)) {
      throw new Error(`Dependency graph referenced node with id ${dependentId}, which was not in the node list`);
    }

    const subjectNode = this.nodes.get(subjectId);
    const dependentNode = this.nodes.get(dependentId);

    if (visited.has(dependentId)) {
      throw new Error(`Circular dependency detected involving node with id ${dependentId}`);
    }

    visited.add(dependentId);

    subjectNode.dependedOnBy.add(dependentId);
    dependentNode.dependsOn.add(subjectId);

    dependentNode.dependedOnBy.forEach((id) => {
      this.addDependency(subjectId, id, new Set([...visited]));
    });
  }

  hasCircularDependencies() {
    const visited = new Set();
    const inProgress = new Set();

    const hasCycle = (nodeId) => {
      if (inProgress.has(nodeId)) {
        return true;
      }
      if (visited.has(nodeId)) {
        return false;
      }

      visited.add(nodeId);
      inProgress.add(nodeId);

      for (const dependentId of this.nodes.get(nodeId).dependsOn) {
        if (hasCycle(dependentId)) {
          return true;
        }
      }

      inProgress.delete(nodeId);
      return false;
    };

    for (const nodeId of this.nodes.keys()) {
      if (hasCycle(nodeId)) {
        return true;
      }
    }

    return false;
  }
}

// Example usage
const graph = new DependencyGraph();
graph.addNode('A');
graph.addNode('B');
graph.addNode('C');
graph.addDependency('A', 'B');
graph.addDependency('B', 'C');
graph.addDependency('C', 'A');
console.log(graph.hasCircularDependencies()); // Output: true
```

