public class FSMGenerator {
    public static String generateFSMDOT(List<String> states, List<Tuple<String, String, String>> transitions) {
        StringBuilder dotRepresentation = new StringBuilder();
        dotRepresentation.append("digraph finite_state_machine {\n");
        dotRepresentation.append("    rankdir=LR;\n");
        dotRepresentation.append("    size=\"8,5\"\n");
        dotRepresentation.append("    node [shape = circle]; ");

        for (String state : states) {
            dotRepresentation.append(state).append(" ");
        }

        dotRepresentation.append(";\n");
        dotRepresentation.append("    node [shape = doublecircle]; ").append(states.get(0)).append(";\n");

        for (Tuple<String, String, String> transition : transitions) {
            dotRepresentation.append("    ").append(transition.getFirst()).append(" -> ").append(transition.getSecond())
                    .append(" [ label = \"").append(transition.getThird()).append("\" ];\n");
        }

        dotRepresentation.append("}");

        return dotRepresentation.toString();
    }
}
```

