    std::vector<std::vector<int>> graph;
    std::vector<int> ids, low;
    std::vector<bool> onStack;
    std::stack<int> stack;
    int id, sccCount;

    void dfs(int at) {
        stack.push(at);
        onStack[at] = true;
        ids[at] = low[at] = id++;

        for (int to : graph[at]) {
            if (ids[to] == -1) {
                dfs(to);
                low[at] = std::min(low[at], low[to]);
            } else if (onStack[to]) {
                low[at] = std::min(low[at], ids[to]);
            }
