### Solution:
```rust
use std::ptr;

struct Node<T> {
    value: T,
    next: Option<Box<Node<T>>>,
}

pub struct Queue<T> {
    head: Option<Box<Node<T>>>,
    tail: *mut Node<T>,
}

impl<T> Queue<T> {
    pub fn new() -> Self {
        Queue { head: None, tail: ptr::null_mut() }
    }

    pub fn enqueue(&mut self, value: T) {
        let mut new_tail = Box::new(Node { value, next: None });
        let raw_tail: *mut _ = &mut *new_tail;
        if !self.tail.is_null() {
            unsafe { (*self.tail).next = Some(new_tail) };
        } else {
            self.head = Some(new_tail);
        }
        self.tail = raw_tail;
    }

    pub fn dequeue(&mut self) -> Option<T> {
        self.head.take().map(|head| {
            let head = *head;
            self.head = head.next;
            if self.head.is_none() {
                self.tail = ptr::null_mut();
            }
            head.value
        })
    }

    pub fn peek(&self) -> Option<&T> {
        self.head.as_ref().map(|head| &head.value)
    }

    pub fn is_empty(&self) -> bool {
        self.head.is_none()
    }
}

fn main() {
    let mut queue: Queue<i32> = Queue::new();
    queue.enqueue(10);
    queue.enqueue(20);
    queue.enqueue(30);
    println!("Peek: {:?}", queue.peek()); // Output: Peek: Some(10)
    println!("Dequeue: {:?}", queue.dequeue()); // Output: Dequeue: Some(10)
    println!("Is empty: {}", queue.is_empty()); // Output: Is empty: false
}
```

