```

You can assume that the graph is acyclic and that there is at most one edge between any pair of nodes.

For example, given the following graph:
```
A -> B -> C
|    |
v    v
D -> E
```
If `start` is A and `target` is C, the function should return a vector containing the nodes A, B, and C.

### Solution:
```cpp
#include <vector>
#include <queue>
#include <unordered_map>

std::vector<Node*> shortestPath(Node* start, Node* target) {
    std::unordered_map<Node*, Node*> parentMap;
    std::queue<Node*> queue;
    queue.push(start);
    parentMap[start] = nullptr;

    while (!queue.empty()) {
        Node* current = queue.front();
        queue.pop();

        if (current == target) {
            std::vector<Node*> path;
            while (current != nullptr) {
                path.push_back(current);
                current = parentMap[current];
            }
            std::reverse(path.begin(), path.end());
            return path;
        }

        for (Node* neighbor = current->GetArc(); neighbor != nullptr; neighbor = neighbor->GetArc()) {
            if (parentMap.find(neighbor) == parentMap.end()) {
                parentMap[neighbor] = current;
                queue.push(neighbor);
            }
        }
    }

    return std::vector<Node*>();
}
```

