    "A": vec!["B", "C"],
    "B": vec!["D"],
    "C": vec!["E"],
    "D": vec!["F"],
    "E": vec!["G"],
    "F": vec![],
    "G": vec!["H"],
    "H": vec![]
}
```
The function `find_max_distance_node` should return `"A"` as the node with the maximum sum of distances to all other nodes.

### Solution:
```rust
use std::collections::{HashMap, HashSet};

fn part1_bfs<'a>(u: &'a str, graph: &HashMap<&'a str, Vec<&'a str>>, visited: &mut HashMap<&'a str, bool>, dist: u32) -> u32 {
    if visited.contains_key(u) && *visited.get(u).unwrap() {
        return 0;
    }

    visited.insert(u, true);

    let mut sum = dist;
    for v in graph.get(u).unwrap() {
        sum += part1_bfs(v, graph, visited, dist + 1);
    }

    sum
}

fn find_max_distance_node(graph: &HashMap<&str, Vec<&str>>) -> &str {
    let mut max_distance = 0;
    let mut max_node = "";

    for (node, _) in graph.iter() {
        let mut visited = HashMap::new();
        let distance = part1_bfs(node, graph, &mut visited, 0);
        if distance > max_distance {
            max_distance = distance;
            max_node = node;
        }
    }

    max_node
}

