use petgraph::graph::BaseGraph;
use std::collections::HashSet;

impl YourStruct {
    fn get_missing_edge<G: BaseGraph>(&self, graph: &G) -> Option<(usize, usize)> {
        let mut vertices: HashSet<_> = (0..graph.node_count()).collect();
        graph.edge_indices().for_each(|edge| {
            let (source, target) = graph.edge_endpoints(edge).unwrap();
            vertices.remove(&source);
            vertices.remove(&target);
        });

        if vertices.len() == 2 {
            Some((*vertices.iter().next().unwrap(), *vertices.iter().nth(1).unwrap()))
        } else {
            None
        }
    }
}
