```php
class IbuyproAlgorithm
{
    /**
     * @var Graph $graph
     */
    private $graph = null;
    private $startTopNumber = null;
    private $pathTops = [];

    public function __construct(Graph $graph, int $startTopNumber)
    {
        $this->graph = $graph;
        $this->startTopNumber = $startTopNumber;
    }

    public function findShortestPath()
    {
        $distances = array_fill(0, $this->graph->getVertexCount(), INF);
        $distances[$this->startTopNumber] = 0;

        $visited = array_fill(0, $this->graph->getVertexCount(), false);

        for ($i = 0; $i < $this->graph->getVertexCount() - 1; $i++) {
            $minDistance = INF;
            $minIndex = -1;

            for ($j = 0; $j < $this->graph->getVertexCount(); $j++) {
                if (!$visited[$j] && $distances[$j] < $minDistance) {
                    $minDistance = $distances[$j];
                    $minIndex = $j;
                }
            }

            $visited[$minIndex] = true;

            for ($k = 0; $k < $this->graph->getVertexCount(); $k++) {
                if (!$visited[$k] && $this->graph->hasEdge($minIndex, $k) && $distances[$minIndex] + $this->graph->getEdgeWeight($minIndex, $k) < $distances[$k]) {
                    $distances[$k] = $distances[$minIndex] + $this->graph->getEdgeWeight($minIndex, $k);
                    $this->pathTops[$k] = $minIndex;
                }
            }
        }
    }

    public function getShortestPath(int $destinationTopNumber)
    {
        $path = [];
        $currentTop = $destinationTopNumber;

        while ($currentTop != $this->startTopNumber) {
            $path[] = $currentTop;
            $currentTop = $this->pathTops[$currentTop];
        }

        $path[] = $this->startTopNumber;
        $path = array_reverse($path);

        return $path;
    }
}
