### Solution:
```csharp
public interface INode
{
    IEnumerable<INode> Children { get; }
}

public class BaseNode : INode
{
    public virtual IEnumerable<INode> Children => Enumerable.Empty<INode>();
}

public class BlockStatementNode : BaseNode, IStatementNode
{
    public IStatementNode[] Body { get; set; }

    public override IEnumerable<INode> Children
    {
        get
        {
            foreach (var node in Body)
            {
                yield return node;
            }
        }
    }
}

public class ASTNodeCounter
{
    public int CountNodes(INode root)
    {
        int count = 1; // Count the current node
        var queue = new Queue<INode>();
        queue.Enqueue(root);

        while (queue.Count > 0)
        {
            var currentNode = queue.Dequeue();
            foreach (var childNode in currentNode.Children)
            {
                count++; // Count the child node
                queue.Enqueue(childNode);
            }
        }

        return count;
    }
}
```

The `CountNodes` method uses a breadth-first search approach to traverse the AST and count the total number of nodes. It starts with the root node and iteratively processes each node's children, incrementing the count for each node encountered. Finally, it returns the total count of nodes in the AST.

