### Solution:
```cpp
#include <queue>
#include <unordered_set>

TaskNode* scheduleTasks(TaskNode* initial_node) {
  // Perform a topological sort to determine the order of task execution
  queue<TaskNode*> taskQueue;
  unordered_set<TaskNode*> visited;

  function<void(TaskNode*)> topologicalSort = [&](TaskNode* node) {
    for (TaskNode* dependency : node->dependencies) {
      if (visited.find(dependency) == visited.end()) {
        topologicalSort(dependency);
      }
    }
    taskQueue.push(node);
    visited.insert(node);
  };

  topologicalSort(initial_node);

  // Calculate the earliest completion time for each task
  while (!taskQueue.empty()) {
    TaskNode* current = taskQueue.front();
    taskQueue.pop();

    int wait_until = current->start_time;
    for (TaskNode* dependency : current->dependencies) {
      wait_until = max(wait_until, dependency->latest_time);
    }
    current->wait_until = wait_until;
    current->latest_time = wait_until + current->duration;
  }

  return initial_node;
}
```

In the solution, we first perform a topological sort to determine the order in which tasks should be executed, considering their dependencies. Then, we iterate through the sorted tasks to calculate the earliest completion time for each task, taking into account the wait time due to dependencies. Finally, we update the `latest_time` and `wait_until` properties for each task and return the updated initial task node.

